573	    static List<URL> resolveCommandLocationUrls(String commandLocations, String arthasHome, Logger logger)
574	                    throws IOException {
575	        List<CommandLocation> locations = collectCommandLocations(commandLocations, arthasHome);
576	        if (locations.isEmpty()) {
577	            return Collections.emptyList();
578	        }
579	
580	        Map<String, URL> commandUrls = new LinkedHashMap<String, URL>();
581	        for (CommandLocation location : locations) {
582	            File file = new File(location.path());
583	            if (!file.exists()) {
584	                logger.warn("Skip arthas external command location because it does not exist: {}", location.path());
585	                continue;
586	            }
587	
588	            if (file.isDirectory()) {
589	                File[] jarFiles = file.listFiles(new FileFilter() {
590	                    @Override
591	                    public boolean accept(File pathname) {
592	                        return pathname.isFile() && isCommandJar(pathname);
593	                    }
594	                });
595	                if (jarFiles == null || jarFiles.length == 0) {
596	                    continue;
597	                }
598	                Arrays.sort(jarFiles, new Comparator<File>() {
599	                    @Override
600	                    public int compare(File left, File right) {
601	                        return left.getName().compareTo(right.getName());
602	                    }
603	                });
604	                for (File jarFile : jarFiles) {
605	                    addCommandUrl(commandUrls, jarFile);
606	                }
607	            } else if (file.isFile() && isCommandJar(file)) {
608	                addCommandUrl(commandUrls, file);
609	            } else {
610	                logger.warn("Skip arthas external command location because it is not a jar file or directory: {}",
611	                                location.path());
612	            }
613	        }
614	
615	        return new ArrayList<URL>(commandUrls.values());
616	    }
